"use strict";

// A class declared inside a factory, with untyped (implicit-any, monomorphized) methods that read the factory's
// bindings, in mysql2's shape (a command class minted per connection). A method read off an instance is the
// function of ONE evaluation: its captured bindings are that evaluation's, whatever receiver it is called on.
function make(prefix, n) {
  class C {
    constructor() {
      this.v = n;
    }
    add(x) {
      return prefix + x + n;
    }
    both(x) {
      return prefix + x + this.v;
    }
    viaArrow(x) {
      return [1, 2].map((y) => prefix + y + x + this.v).join(",");
    }
    noop() {
      return 7;
    }
  }
  return new C();
}

module.exports = { make };
